<?php
declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN','VERIFICADOR']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;font-family:Manrope,Arial,sans-serif;color:#172033}.wrap{max-width:980px;margin:auto;padding:82px 14px 32px}h1{margin:0 0 5px}.sub{color:#64748b;margin-bottom:18px}.filters{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;background:#fff;padding:12px;border-radius:14px;margin-bottom:14px}.filters input,.filters button,.filters a{padding:10px;border-radius:9px;border:1px solid #cbd5e1;font:inherit}.filters button{background:#172033;color:#fff;font-weight:800}.filters a{background:#e8eef2;color:#172033;text-decoration:none;font-weight:800;text-align:center}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.card,.panel{background:#fff;border-radius:15px;padding:15px;box-shadow:0 3px 12px #0f172a0d}.n{font-size:24px;font-weight:900}.l{font-size:11px;color:#64748b;text-transform:uppercase;font-weight:800}.panel{margin-top:12px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #eef2f7;font-size:13px}@media(max-width:700px){.filters{grid-template-columns:1fr 1fr}.filters button,.filters a{grid-column:span 1}.cards{grid-template-columns:1fr 1fr}}</style></head><body><main class="wrap"><h1>Reportes</h1><div class="sub">Finanzas y actividad por periodo</div><div class="filters"><input id="desde" type="date"><input id="hasta" type="date"><button id="ver">Actualizar</button><a id="csv">Exportar CSV</a></div><div id="cards" class="cards"></div><div class="panel"><h3>Mes a mes</h3><table><thead><tr><th>Periodo</th><th>Mov.</th><th>Total</th><th>Mens.</th><th>Inscr.</th><th>Intens.</th></tr></thead><tbody id="meses"></tbody></table></div><div class="panel"><h3>Asistencia</h3><div id="asis"></div></div></main><script>const d=document.getElementById('desde'),h=document.getElementById('hasta'),c=document.getElementById('cards'),m=document.getElementById('meses'),a=document.getElementById('asis'),csv=document.getElementById('csv');const now=new Date();d.value=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10);h.value=new Date(now.getFullYear(),now.getMonth()+1,0).toISOString().slice(0,10);const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN'});async function load(){const r=await fetch(`/api/reportes.php?desde=${d.value}&hasta=${h.value}`),x=await r.json();if(!x.ok)return;c.innerHTML=`<div class="card"><div class="n">${money(x.finanzas.total)}</div><div class="l">Total recibido</div></div><div class="card"><div class="n">${money(x.finanzas.mensualidades_total)}</div><div class="l">Mensualidades</div></div><div class="card"><div class="n">${money(x.finanzas.inscripciones_total)}</div><div class="l">Inscripciones</div></div><div class="card"><div class="n">${money(x.finanzas.intensivos_total)}</div><div class="l">Intensivos</div></div>`;m.innerHTML=x.meses.map(z=>`<tr><td>${z.periodo}</td><td>${z.movimientos}</td><td>${money(z.total)}</td><td>${money(z.mensualidades)}</td><td>${money(z.inscripciones)}</td><td>${money(z.intensivos)}</td></tr>`).join('')||'<tr><td colspan="6">Sin datos</td></tr>';a.textContent=`Presentes: ${x.asistencia.presentes||0} · Justificadas: ${x.asistencia.justificadas||0} · No justificadas: ${x.asistencia.no_justificadas||0}`;csv.href=`/api/reportes-exportar.php?desde=${d.value}&hasta=${h.value}`;}document.getElementById('ver').onclick=load;load();</script></body></html>